545	\begin{lemma}\label{lem:leastGT_predictablePart_le}
546	  \uses{def:predictablePart, def:leastGT}
547	Let $X$ be a real adapted process and let $A$ be its predictable part. Let $c \in \mathbb{R}$.
548	Then $A_{\tau_{A_{n + 1} > c}} \le c$ and if $\tau_{A_{n + 1} > c} < \infty$ then $A_{\tau_{A_{n + 1} > c} + 1} > c$.
549	\end{lemma}
550	
551	\begin{proof}
552	  \uses{lem:centering_basic}
553	
554	\end{proof}
