557	\begin{lemma}\label{lem:leastGT_predictablePart_sub_ge}
558	  \uses{def:predictablePart, def:leastGT}
559	Let $X$ be a real adapted process and let $A$ be its predictable part.
560	Let $a, b \in \mathbb{R}$ with $a \le b$.
561	If $\tau_{A_{n + 1} > b} < \infty$ then $A_{\tau_{A_{n + 1} > b}+1} - A_{\tau_{A_{n + 1} > a}} \ge b - a$.
562	\end{lemma}
563	
564	\begin{proof}
565	  \uses{lem:leastGT_predictablePart_le}
566	
567	\end{proof}
