570	\begin{lemma}\label{lem:uniformIntegrable_predictablePart_aux1}
571	  \uses{def:predictablePart, def:martingalePart}
572	Let $T \in \mathbb{N}$ and let $X$ be an adapted process with $X_n$ integrable for all $n$ and such that $X_T = 0$.
573	Then for a stopping time $\tau \le T$, almost surely, $M_\tau = -\mathbb{E}[A_T \mid \mathcal{F}_\tau]$ and $X_\tau = A_\tau - \mathbb{E}[A_T \mid \mathcal{F}_\tau]$.
574	\end{lemma}
575	
576	\begin{proof}
577	  \uses{def:martingalePart, lem:martingale_martingalePart, lem:centering_basic}
578	By definition and since $X_T = 0$, $M_T = X_T - A_T = - A_T$.
579	Since $M$ is a martingale it follows by optional sampling that for any stopping time $\tau \le T$
580	\begin{align*}
581	  M_\tau = \mathbb{E}[M_T \mid \mathcal{F}_\tau] = -\mathbb{E}[A_T \mid \mathcal{F}_\tau]
582	  \: .
583	\end{align*}
584	And then $X_\tau = M_\tau + A_\tau = A_\tau - \mathbb{E}[A_T \mid \mathcal{F}_\tau]$.
585	\end{proof}
