592	\begin{lemma}\label{lem:predictablePart_gt_iff_leastGT_lt}
593	  \uses{def:predictablePart}
594	Suppose that $X$ is a submartingale and let $T \ge 1$, $c \in \mathbb{R}$.
595	Then $A_T > c \iff \tau^T(c) < T$.
596	\end{lemma}
597	
598	\begin{proof}
599	  \uses{lem:leastGT_lt_iff, lem:Submartingale.monotone_predictablePart, lem:centering_basic}
600	By Lemma~\ref{lem:leastGT_lt_iff}, $\tau^T(c) < T \iff \exists s < T, A_{s+1} > c$, which is equivalent to $\exists s \in \{1, \ldots, T\}, A_s > c$.
601	By monotonicity of $A$ (Lemma~\ref{lem:Submartingale.monotone_predictablePart}), this is equivalent to $A_T > c$.
602	\end{proof}
603	
604	
605	\begin{lemma}\label{lem:uniformIntegrable_predictablePart_aux2}
606	  \uses{def:predictablePart, def:leastGT}
607	Suppose that $X$ is a submartingale with $X_T = 0$.
608	Then
609	\begin{align*}
610	  \mathbb{E}\left[A_T \mathbb{I}\{A_T > c\} \right]
611	  \le c \mathbb{P}(\tau^T(c) < T) - \int_{\tau^T(c) < T} X_{\tau^T(c)} dP
612	  \: .
613	\end{align*}
614	\end{lemma}
615	
616	\begin{proof}
617	  \uses{lem:predictablePart_gt_iff_leastGT_lt, lem:leastGT_predictablePart_le, lem:uniformIntegrable_predictablePart_aux1}
618	By Lemma~\ref{lem:predictablePart_gt_iff_leastGT_lt},
619	\begin{align*}
620	  \mathbb{E}\left[A_T \mathbb{I}\{A_T > c\} \right]
621	  = \mathbb{E}\left[A_T \mathbb{I}\{\tau^T(c) < T\} \right]
622	\end{align*}
623	Since that last event is $\mathcal{F}_{\tau^T(c)}$-measurable, we can apply the tower property of conditional expectation to get
624	\begin{align*}
625	  \mathbb{E}\left[A_T \mathbb{I}\{\tau^T(c) < T\} \right]
626	  = \int_{\tau^T(c) < T} \mathbb{E}[A_T \mid \mathcal{F}_{\tau^T(c)}] dP
627	\end{align*}
628	Now by Lemma~\ref{lem:uniformIntegrable_predictablePart_aux1} and Lemma~\ref{lem:leastGT_predictablePart_le},
629	\begin{align*}
630	  \mathbb{E}\left[A_T \mathbb{I}\{\tau^T(c) < T\} \right]
631	  &= \int_{\tau^T(c) < T} A_{\tau^T(c)} - X_{\tau^T(c)} dP
632	  \\
633	  &\le c \mathbb{P}(\tau^T(c) < T) - \int_{\tau^T(c) < T} X_{\tau^T(c)} dP
634	  \: .
635	\end{align*}
636	\end{proof}
637	
638	
639	\begin{lemma}\label{lem:uniformIntegrable_predictablePart_aux3}
640	  \uses{def:predictablePart, def:leastGT}
641	Suppose that $X$ is a submartingale with $X_T = 0$.
642	Then
643	\begin{align*}
644	  \mathbb{P}(\tau^T(c) < T)
645	  &\le - \frac{2}{c} \int_{\tau^T(c/2) < T} X_{\tau^T(c/2)} dP
646	  \: .
647	\end{align*}
648	\end{lemma}
649	
650	\begin{proof}
651	  \uses{lem:leastGT_predictablePart_sub_ge, lem:uniformIntegrable_predictablePart_aux1}
652	Notice that $\{\tau^T(c)<T\}\subseteq \{\tau^T(c/2)<T\}$, thus
653	\begin{align*}
654	  \int_{\tau^T(c/2)<T} -X_{\tau^T(c/2)}dP
655	  &=\int_{\tau^T(c/2)<T}\mathbb{E}[A_T \mid \mathcal{F}_{\tau^T(c/2)}] - A_{\tau^T(c/2)} dP
656	  \\
657	  &= \int_{\tau^T(c/2)<T}A_T - A_{\tau^T(c/2)}dP
658	  \\
659	  &\geq \int_{\tau^T(c)<T}A_T - A_{\tau^T(c/2)}dP
660	  \\
661	  \intertext{(over the event $\{\tau^T(c)<T\}$ $A_T\geq c$ and $A_{\tau^T(c/2)}\leq c/2$, thus $A_T - A_{\tau^T(c/2)}\geq c/2$)}
662	  &\ge \frac{c}{2}P(\tau^T(c)<T)
663	  \: .
664	\end{align*}
665	\end{proof}
