668	\begin{lemma}\label{lem:uniformIntegrable_predictablePart_aux4}
669	  \uses{def:predictablePart, def:leastGT}
670	Suppose that $X$ is a submartingale with $X_T = 0$.
671	Then
672	\begin{align*}
673	  \mathbb{E}\left[A_T \mathbb{I}\{A_T > c\} \right]
674	  \le - 2 \int_{\tau^T(c/2) < T} X_{\tau^T(c/2)} dP - \int_{\tau^T(c) < T} X_{\tau^T(c)} dP
675	  \: .
676	\end{align*}
677	\end{lemma}
678	
679	\begin{proof}
680	  \uses{lem:uniformIntegrable_predictablePart_aux2, lem:uniformIntegrable_predictablePart_aux3}
681	Put together the bounds of Lemma~\ref{lem:uniformIntegrable_predictablePart_aux2} and Lemma~\ref{lem:uniformIntegrable_predictablePart_aux3}.
682	\end{proof}
