685	\begin{lemma}\label{lem:uniformIntegrable_predictablePart_aux5}
686	  \uses{def:predictablePart, def:leastGT}
687	Suppose that $X$ is a submartingale with $X_T = 0$.
688	Then
689	\begin{align*}
690	  P(\tau^T(c) < T) \le -\frac{\mathbb{E}[X_0]}{c} \: .
691	\end{align*}
692	\end{lemma}
693	
694	\begin{proof}
695	  \uses{lem:predictablePart_gt_iff_leastGT_lt, lem:martingale_martingalePart}
696	Starting with Lemma~\ref{lem:predictablePart_gt_iff_leastGT_lt},
697	\begin{align*}
698	  P(\tau^T(c)<T)
699	  =P(A_T>c)
700	  \stackrel{Markov}{\leq}\frac{\mathbb{E}[A_T]}{c}
701	  =-\frac{\mathbb{E}[M_T]}{c}
702	  \stackrel{mg}{=}-\frac{\mathbb{E}[X_0]}{c}
703	  \: .
704	\end{align*}
705	\end{proof}
